const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function readWishlist(storage=globalThis.localStorage){try{const list=JSON.parse(storage.getItem('nm-wishlist')||'[]');return Array.isArray(list)?[...new Set(list.filter(id=>typeof id==='string'&&/^[a-z0-9-]{1,48}$/.test(id)))].slice(0,200):[]}catch{return []}}
export function productBadge(p,now=Date.now()){if(p.releaseLabel==='Erweitert')return 'Erweitert';if(p.releaseLabel==='Neu'||p.createdAt>now-30*86400000&&p.createdAt<=now)return 'Neu';return ''}
export function relatedProducts(p,products){const ids=(p.relatedIds||'').split(',').map(s=>s.trim()).filter(Boolean);if(!ids.length)return products.filter(q=>q.id!==p.id&&q.category===p.category).slice(0,3);return products.filter(q=>q.id!==p.id&&ids.includes(q.id)).sort((a,b)=>ids.indexOf(a.id)-ids.indexOf(b.id)).slice(0,3)}
export function updateNotice(p){return p.version||p.changeNotes?`<div class="package-update"><strong>${p.version?'Paketversion '+escape(p.version):'Paketinformationen'}</strong>${p.changeNotes?`<p>${escape(p.changeNotes)}</p>`:''}<small>Aktuell bereitgestellter Stand. Es wird keine zusätzliche Update-Zusage begründet.</small></div>`:''}
export function wishButton(p){return `<button class="button wish-button" data-wish="${escape(p.id)}" aria-pressed="${readWishlist().includes(p.id)}" aria-label="${readWishlist().includes(p.id)?'Aus Merkliste entfernen':'Auf Merkliste setzen'}">${readWishlist().includes(p.id)?'♥ Gemerkt':'♡ Merken'}</button>`}
export function badgeMarkup(p){const label=productBadge(p);return label?`<span class="discovery-badge">${label}</span>`:''}
export function mountDiscovery({getProducts,renderCard,toast,onWishlistChange}){
 if(!document.querySelector('link[href="/discovery.css"]')){const link=document.createElement('link');link.rel='stylesheet';link.href='/discovery.css';document.head.append(link);}
 document.addEventListener('click',e=>{const b=e.target.closest('[data-wish]');if(!b)return;const id=b.dataset.wish,old=readWishlist();if(!getProducts().some(p=>p.id===id))return;const next=old.includes(id)?old.filter(x=>x!==id):[...old,id];if(next.length>200){toast('Deine Merkliste enthält bereits 200 Produkte.');return}try{localStorage.setItem('nm-wishlist',JSON.stringify(next))}catch{toast('Dein Browser erlaubt das Speichern der Merkliste gerade nicht.');return}sync();onWishlistChange();toast(next.includes(id)?'Auf deiner Merkliste gespeichert.':'Von deiner Merkliste entfernt.');});
 function sync(){document.querySelectorAll('[data-wish]').forEach(b=>{const saved=readWishlist().includes(b.dataset.wish);b.setAttribute('aria-pressed',String(saved));b.setAttribute('aria-label',saved?'Aus Merkliste entfernen':'Auf Merkliste setzen');b.textContent=saved?'♥ Gemerkt':'♡ Merken'})}
 window.addEventListener('storage',e=>{if(e.key==='nm-wishlist'){sync();onWishlistChange()}});
 return {wishlist(view){const list=getProducts().filter(p=>readWishlist().includes(p.id));view.innerHTML=`<section class="page panel discovery-page"><span class="kicker">DEINE AUSWAHL · DEIN STIL</span><h1>Meine Merkliste</h1><p>Auf diesem Gerät gespeichert, auch ohne Anmeldung. Keine Synchronisierung zwischen Geräten. Beim Löschen der Browserdaten wird auch diese Liste entfernt.</p>${list.length?`<div class="discovery-grid">${list.map(renderCard).join('')}</div>`:'<div class="empty"><h2>Platz für deine Lieblingsdesigns.</h2><p>Tippe bei einem Paket auf „♡ Merken“.</p><a class="button primary" href="/collections">Designs entdecken →</a></div>'}</section>`},product(p){
 const layout=document.querySelector('.product-layout');if(!layout)return;
 const media=layout.firstElementChild,img=media.querySelector('.product-image');
 if(img&&p.category==='Wallpaper'){
  img.insertAdjacentHTML('beforebegin','<div class="device-controls" role="group" aria-label="Vorschauansicht"><button class="button" data-device="original" aria-pressed="true">Original</button><button class="button" data-device="monitor" aria-pressed="false" disabled>Monitor</button><button class="button" data-device="phone" aria-pressed="false" disabled>Handy</button></div>');
  const stage=document.createElement('div');stage.className='device-stage';stage.dataset.device='original';stage.dataset.product=p.id;stage.dataset.overview=img.getAttribute('src');img.replaceWith(stage);const screen=document.createElement('div');screen.className='device-screen';screen.append(img);stage.append(screen);stage.insertAdjacentHTML('afterend','<p class="muted device-hint">Die Geräteansicht zeigt ein einzelnes Vorschaumotiv als Zuschnitt. Enthaltene Formate und Auflösungen stehen rechts in den Paketinformationen.</p>');
  media.querySelectorAll('[data-device]').forEach(b=>b.onclick=()=>{stage.dataset.device=b.dataset.device;img.src=b.dataset.device==='original'?stage.dataset.overview:stage.dataset.motif;const picker=media.querySelector('.device-motifs');if(picker)picker.hidden=b.dataset.device==='original';media.querySelectorAll('button[data-device]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)))});
 }
 const details=layout.querySelector('.detail-list');if(details)details.outerHTML=`<section class="package-facts"><h2>Das ist im Paket enthalten</h2><dl><div><dt>Lieferumfang</dt><dd>${p.contents}</dd></div><div><dt>Formate & Auflösung</dt><dd>${p.formats}${p.resolutions?`<br>${p.resolutions}`:''}</dd></div><div><dt>Downloadgröße</dt><dd>${p.packageBytes?new Intl.NumberFormat('de-DE',{maximumFractionDigits:1}).format(p.packageBytes/1048576)+' MB (ZIP)':p.category==='Designservice'?'Nach vereinbartem Leistungsumfang':'Wird mit dem fertigen Paket ergänzt'}</dd></div></dl></section>`;
 const copy=layout.querySelector('.product-copy');copy.insertAdjacentHTML('beforeend',wishButton(p)+updateNotice(p));copy.querySelector('.kicker')?.insertAdjacentHTML('afterend',badgeMarkup(p));
 const related=relatedProducts(p,getProducts());if(related.length)layout.parentElement.insertAdjacentHTML('beforeend',`<section class="panel related-packages"><span class="kicker">${p.relatedIds?'VON NEONMIND AUSGEWÄHLT':'MEHR AUS DIESER KATEGORIE'}</span><h2>Passt zu deiner Auswahl</h2><div class="discovery-grid">${related.map(renderCard).join('')}</div></section>`);
 },gallery(id,pictures){
 const stage=document.querySelector('.device-stage');if(!stage||stage.dataset.product!==id)return;
 const motifs=pictures.filter(p=>typeof p.image==='string'&&(new RegExp('^/api/gallery-image/'+id+'/[0-9]+$').test(p.image)||new RegExp('^/assets/package-previews/'+id+'/[0-9]+\\.jpg$').test(p.image)));if(!motifs.length)return;
 const media=stage.parentElement,img=stage.querySelector('img');stage.dataset.motif=motifs[0].image;stage.dataset.clean=String(motifs[0].clean===true);
 media.querySelectorAll('button[data-device]').forEach(b=>b.disabled=false);
 const picker=document.createElement('div');picker.className='device-motifs';picker.hidden=stage.dataset.device==='original';picker.setAttribute('role','group');picker.setAttribute('aria-label','Einzelmotiv für Geräteansicht wählen');
 motifs.forEach((p,i)=>{const b=document.createElement('button');b.type='button';b.className='device-motif';b.setAttribute('aria-label','Motiv '+(i+1)+' in Geräteansicht zeigen');b.setAttribute('aria-pressed',String(i===0));const thumb=document.createElement('img');thumb.src=p.image;thumb.alt='';thumb.loading='lazy';b.append(thumb);b.onclick=()=>{stage.dataset.motif=p.image;stage.dataset.clean=String(p.clean===true);img.src=p.image;img.alt='Einzelmotiv '+(i+1)+' – Geräteansicht';picker.querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed',String(x===b)))};picker.append(b)});
 stage.after(picker);if(stage.dataset.device!=='original')img.src=stage.dataset.motif;
 }};
}
export function aboutPage(){return `<section class="page panel discovery-page"><div class="about-neonmind"><img src="/assets/brand-logo.png" alt="NeonMind Ringlogo"><div><span class="kicker">DER MENSCH HINTER DEN DESIGNS</span><h1>Markus. NeonMind.</h1><p>Hinter NeonMind stehe ich, Markus Niggemeier. Hier kommen meine digitalen Designs und eigenen Softwareprojekte zusammen.</p><p>Leuchtende Farben, Musik und digitale Oberflächen prägen den Stil. Von Bildschirmmotiven bis zu Apps entsteht daraus Schritt für Schritt eine gemeinsame Designwelt.</p><p>Zu den Projekten gehören NeonMind Gallery und FindMe. Im Shop findest du digitale Designpakete und kannst eigene Gestaltungswünsche anfragen.</p><div class="about-actions"><a class="button primary" href="/collections">Designs entdecken →</a><a class="button" href="/wuensche">Deine Idee erzählen →</a><a class="button" href="https://neonmind-ai.com/">Apps & Projekte ↗</a></div></div></div></section>`}
